"""Curated selection for the history layer. Every place is resolved on Wikidata
from its English Wikipedia title (or a QID) so coordinates and QIDs come from Wikidata.
Dates are rounded values (negative = BCE) taken from the cited Wikipedia articles."""

WP = "https://en.wikipedia.org/wiki/"
def S(title, url): return {"title": title, "url": url}
def P(ref, type, start=None, end=None, note=None, name=None):
    return dict(ref=ref, type=type, start=start, end=end, note=note, name=name)
def C(ref, start=None, end=None, name=None): return dict(ref=ref, start=start, end=end, name=name)
def POL(id, name, start, end, peak, qid, caps, ext=None, extnote=None):
    # ext = (basemap year key, [feature NAMEs]) or None
    return dict(id=id, name=name, start=start, end=end, peak=peak, qid=qid, caps=caps, ext=ext, extnote=extnote)
def R(name, type, wps, source, conf, note): return dict(name=name, type=type, waypoints=wps, source=source, confidence=conf, note=note)

BASEMAP_YEARS = ["bc2000","bc1000","bc500","bc200","100","400","600","700","800","1000","1100","1300","1500","1530","1700","1783","1815","1880","1960"]

